mapper.select:

WHERE conversation_id = #{conversationId}
ORDER BY id DESC
LIMIT #{limit}

mapper.update:
UPDATE terra_conversation
SET message_count = (
        SELECT COUNT(*) FROM terra_message WHERE conversation_id = #{conversationId}
    ),
    last_message_time = (
        SELECT MAX(create_time) FROM terra_message WHERE conversation_id = #{conversationId}
    )
WHERE id = #{conversationId}
